window.docContents[82].resolve({"/Automation/#Logical-Foundations--Automation___-More-Automation--Case-Study___-Regular-Expressions--The-___Weak___-Pumping-Lemma":{"contents":"\n\nThe remainder of this section in the full version of the chapter develops an extended\nexercise on regular expressions, leading up to a proof of the\nso-called pumping lemma, which states, informally, that any sufficiently\nlong string s matching a regular expression re can be \"pumped\" by\nrepeating some middle section of s an arbitrary number of times to produce a new\nstring also matching re.\n\n\n\n","context":"Logical Foundations\u0009Automation: More Automation\u0009Case Study: Regular Expressions","header":"10.5.4. The \"Weak\" Pumping Lemma","id":"/Automation/#Logical-Foundations--Automation___-More-Automation--Case-Study___-Regular-Expressions--The-___Weak___-Pumping-Lemma"},"/Poly/#Logical-Foundations--Poly___-Polymorphism-and-Higher-Order-Functions--Polymorphism":{"contents":"\n\n\n\n\n\n\n\n","context":"Logical Foundations\u0009Poly: Polymorphism and Higher-Order Functions","header":"6.1. Polymorphism","id":"/Poly/#Logical-Foundations--Poly___-Polymorphism-and-Higher-Order-Functions--Polymorphism"},"/Preface/#Logical-Foundations--Preface--For-Potential-Contributors":{"contents":"If you find things you'd like to help add or improve, your\ncontributions are welcome!  To get started, clone the\nSF-in-Lean git repo and\nhave a look at ALPHA-TESTERS.md.\n\n","context":"Logical Foundations\u0009Preface","header":"1.4. For Potential Contributors","id":"/Preface/#Logical-Foundations--Preface--For-Potential-Contributors"}});